'use strict';

// MODULES //

var bench = require( '@stdlib/bench' );
var discreteUniform = require( '@stdlib/random/array/discrete-uniform' );
var Float64Array = require( '@stdlib/array/float64' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var pow = require( '@stdlib/math/base/special/pow' );
var floor = require( '@stdlib/math/base/special/floor' );
var format = require( '@stdlib/string/format' );
var pkg = require( './../package.json' ).name;
var dlasr = require( './../lib/ndarray.js' );


// VARIABLES //

var SIDES = [
	'left',
	'right'
];
var PIVOTS = [
	'variable',
	'top',
	'bottom'
];
var DIRECTS = [
	'forward',
	'backward'
];
var opts = {
	'dtype': 'float64'
};


// FUNCTIONS //

/**
* Creates a benchmark function.
*
* @private
* @param {PositiveInteger} N - number of rows and columns
* @param {string} side - specifies the side where plane rotation matrix `P` is applied to `A`
* @param {string} pivot - specifies the plane for which `P(k)` is a plane rotation matrix
* @param {string} direct - specifies whether `P` is a forward or backward sequence of plane rotations
* @returns {Function} benchmark function
*/
function createBenchmark( N, side, pivot, direct ) {
	var A = discreteUniform( N*N, 1.0, 10.0, opts );
	var C = new Float64Array( N );
	var S = new Float64Array( N );
	var i;

	for ( i = 0; i < N; i++ ) {
		C[ i ] = 1.0;
		S[ i ] = 0.0;
	}
	C[ N-1 ] = 0.8;
	S[ N-1 ] = 0.6;

	return benchmark;

	/**
	* Benchmark function.
	*
	* @private
	* @param {Benchmark} b - benchmark instance
	*/
	function benchmark( b ) {
		var i;
		var z;

		b.tic();
		for ( i = 0; i < b.iterations; i++ ) {
			z = dlasr( side, pivot, direct, N, N, C, 1, 0, S, 1, 0, A, N, 1, 0 );
			if ( isnan( z[ i%z.length ] ) ) {
				b.fail( 'should not return NaN' );
			}
		}
		b.toc();
		if ( isnan( z[ i%z.length ] ) ) {
			b.fail( 'should not return NaN' );
		}
		b.pass( 'benchmark finished' );
		b.end();
	}
}


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var direct;
	var pivot;
	var side;
	var min;
	var max;
	var N;
	var f;
	var i;
	var j;
	var l;
	var n;

	min = 1; // 10^min
	max = 6; // 10^max

	for ( j = 0; j < SIDES.length; j++ ) {
		side = SIDES[ j ];
		for ( l = 0; l < PIVOTS.length; l++ ) {
			pivot = PIVOTS[ l ];
			for ( i = 0; i < DIRECTS.length; i++ ) {
				direct = DIRECTS[ i ];
				for ( n = min; n <= max; n++ ) {
					N = floor( pow( pow( 10, n ), 1.0/2.0 ) );
					f = createBenchmark( N, side, pivot, direct );
					bench( format( '%s::square_matrix:ndarray:side=%s,pivot=%s,direct=%s,size=%d', pkg, side, pivot, direct, N*N ), f );
				}
			}
		}
	}
}

main();
